(7429481, 1173280, 104230, '<td valign="top">Wonderful composition, and simplicity. Just a great image. Thank you.</td>', 'Wonderful composition, and simplicity. Just a great image. Thank you.', '2016-01-17 23:13:49.000000', NULL, 1),
(7429483, 1173453, 94815, '<td valign="top">A sensitively constructed composition respecting the flatness and dynamism of the picture plane and the four lines describing its edges. Lines spring from those edges and reframe fields of texture and mood which contrast and contend with each other.  Abstract and deceptively understated, this image is an exercise in minimalism that is at the same time tense with repressed expressionism. It is one of the few that has both a good eye for the art of composition and a feeling for modernist sentiment. If I had a bling to apply, this would get one. voted earlier</td>', 'A sensitively constructed composition respecting the flatness and dynamism of the picture plane and the four lines describing its edges. Lines spring from those edges and reframe fields of texture and mood which contrast and contend with each other.  Abstract and deceptively understated, this image is an exercise in minimalism that is at the same time tense with repressed expressionism. It is one of the few that has both a good eye for the art of composition and a feeling for modernist sentiment. If I had a bling to apply, this would get one. voted earlier', '2016-01-17 23:15:28.000000', NULL, 1),
(7429494, 1173107, 94815, '<td valign="top">I love such spontaneously found images full of both obvious visual parallels and less accessible implications.. voted earlier</td>', 'I love such spontaneously found images full of both obvious visual parallels and less accessible implications.. voted earlier', '2016-01-17 23:33:38.000000', NULL, 1),
